title:
const timerAtom = atom(0)
timerAtom.onMount = (setAtom) => {
  const interval = setInterval(() => {
    setAtom(prev => prev + 1)
  }, 1000)

  return () => clearInterval(interval)  // onUnmount
}
// 구독 시 타이머 시작, 구독 해제 시 타이머 정리

