title:
// 비동기 atom — Promise 반환
const userAtom = atom(async (get) => {
  const id = get(userIdAtom)
  const res = await fetch(`/api/users/${id}`)
  return res.json()
})

// 사용
function UserProfile() {
  const user = useAtomValue(userAtom)  // Suspense와 함께
  return <div>{user.name}</div>
}

